create table public.purchase_budgets(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,category_id bigint references public.categories(id) on delete set null,period text not null,budget_amount numeric(10,2) not null,spent_amount numeric(10,2) not null default 0,remaining_amount numeric(10,2) not null,start_date date not null,end_date date not null,status text not null default 'active',created_by uuid references public.app_users(id) on delete set null,approved_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.budget_alerts(id bigint generated by default as identity primary key,budget_id bigint not null references public.purchase_budgets(id) on delete cascade,business_id bigint not null references public.businesses(id) on delete cascade,alert_type text not null,threshold numeric(5,2) not null,alert_sent_at timestamptz,resolved_at timestamptz,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.budget_transactions(id bigint generated by default as identity primary key,budget_id bigint not null references public.purchase_budgets(id) on delete cascade,purchase_id bigint references public.purchases(id) on delete set null,amount numeric(10,2) not null,transaction_date date not null,reference text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.quality_standards(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,category_id bigint references public.categories(id) on delete set null,temperature_min numeric(5,2),temperature_max numeric(5,2),humidity_min numeric(5,2),humidity_max numeric(5,2),acceptable_defects text,criteria text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.quality_reports(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,supplier_id bigint references public.parties(id) on delete set null,report_date date not null,total_checks integer not null default 0,passed integer not null default 0,failed integer not null default 0,pass_rate numeric(5,2) not null default 0,notes text,generated_by uuid references public.app_users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.supplier_invoices(id bigint generated by default as identity primary key,supplier_id bigint references public.parties(id) on delete set null,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,purchase_id bigint references public.purchases(id) on delete set null,purchase_order_id bigint references public.purchase_orders(id) on delete set null,created_by uuid references public.app_users(id) on delete set null,approved_by uuid references public.app_users(id) on delete set null,invoice_number text not null,invoice_date date not null,due_date date not null,subtotal numeric(10,2) not null default 0,tax_amount numeric(10,2) not null default 0,discount_amount numeric(10,2) not null default 0,total_amount numeric(10,2) not null default 0,status text not null default 'pending',paid_amount numeric(10,2) not null default 0,balance numeric(10,2) not null default 0,currency text not null default 'SAR',payment_terms text not null default 'net_30',notes text,internal_notes text,file_path text,file_name text,file_mime_type text,approved_at timestamptz,sent_at timestamptz,cancelled_at timestamptz,cancellation_reason text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(business_id,invoice_number));
create table public.supplier_invoice_items(id bigint generated by default as identity primary key,supplier_invoice_id bigint not null references public.supplier_invoices(id) on delete cascade,product_id bigint not null references public.products(id) on delete cascade,purchase_detail_id bigint references public.purchase_details(id) on delete set null,description text,quantity integer not null default 0,unit_price numeric(10,2) not null default 0,discount numeric(10,2) not null default 0,tax numeric(10,2) not null default 0,total numeric(10,2) not null default 0,batch_number text,expiry_date date,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.supplier_invoice_payments(id bigint generated by default as identity primary key,supplier_invoice_id bigint not null references public.supplier_invoices(id) on delete cascade,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,created_by uuid references public.app_users(id) on delete set null,approved_by uuid references public.app_users(id) on delete set null,payment_number text not null,payment_date date not null,payment_method text not null,payment_reference text,bank_reference text,amount numeric(10,2) not null,status text not null default 'pending',notes text,approved_at timestamptz,file_path text,file_name text,file_mime_type text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(business_id,payment_number));
do $$ declare t text; begin foreach t in array array['purchase_budgets','budget_alerts','budget_transactions','quality_standards','quality_reports','supplier_invoices','supplier_invoice_items','supplier_invoice_payments'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon,authenticated',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); end loop; end $$;
create policy purchase_budgets_tenant on public.purchase_budgets for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy budget_alerts_tenant on public.budget_alerts for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy budget_transactions_tenant on public.budget_transactions for all to authenticated using((select exists(select 1 from public.purchase_budgets b where b.id=budget_id and b.business_id=(select private.current_business_id())))) with check((select exists(select 1 from public.purchase_budgets b where b.id=budget_id and b.business_id=(select private.current_business_id()))));
create policy quality_standards_tenant on public.quality_standards for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy quality_reports_tenant on public.quality_reports for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy supplier_invoices_tenant on public.supplier_invoices for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy supplier_invoice_items_tenant on public.supplier_invoice_items for all to authenticated using((select exists(select 1 from public.supplier_invoices i where i.id=supplier_invoice_id and i.business_id=(select private.current_business_id())))) with check((select exists(select 1 from public.supplier_invoices i where i.id=supplier_invoice_id and i.business_id=(select private.current_business_id()))));
create policy supplier_invoice_payments_tenant on public.supplier_invoice_payments for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));